	<script>
		document.addEventListener("DOMContentLoaded", function() {
			var toggles = document.querySelectorAll('.elementor-menu-toggle');
			var popup = document.getElementById('mobile-popup-menu');
			var closeBtn = document.getElementById('mobile-popup-close');
			
			if (toggles && popup && closeBtn) {
				toggles.forEach(function(toggle) {
					toggle.addEventListener('click', function(e) {
						e.preventDefault();
						e.stopPropagation();
						popup.classList.add('active');
						document.body.style.overflow = 'hidden';
					});
				});
				
				function closePopup() {
					popup.classList.remove('active');
					document.body.style.overflow = '';
					toggles.forEach(function(t) {
						t.classList.remove('elementor-active');
						t.setAttribute('aria-expanded', 'false');
					});
				}

				closeBtn.addEventListener('click', function(e) {
					e.preventDefault();
					e.stopPropagation();
					closePopup();
				});
				
				// Close popup when clicking on backdrop backdrop
				popup.addEventListener('click', function(e) {
					if (e.target === popup) {
						closePopup();
					}
				});
				
				// Toggle submenus inside popup on click
				var hasChildrenLinks = popup.querySelectorAll('.menu-item-has-children > a');
				hasChildrenLinks.forEach(function(link) {
					link.addEventListener('click', function(e) {
						e.preventDefault();
						e.stopPropagation();
						var parentLi = this.parentElement;
						parentLi.classList.toggle('open');
					});
				});
			}
		});
	</script>
